"""Inspect exact MSPI CQFLAGS metadata and original retention save/low-byte restore."""
import argparse,hashlib,json,struct,xml.etree.ElementTree as ET
from pathlib import Path
from capstone import Cs,CS_ARCH_ARM,CS_MODE_THUMB,CS_MODE_MCLASS
from inspect_mspi1_config_contract import collect
from native_replay import parse_log
from pinned_main import load_pinned_main

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('simulator',type=Path);p.add_argument('output',type=Path);a=p.parse_args();s=a.simulator;o=a.output;o.mkdir(mode=0o700);checks=[];cases=[]
 def check(n,v):
  if not v:raise ValueError(n)
  checks.append(n)
 def marker(log,tag):
  rows=[json.loads(x.split(' ',1)[1]) for x in log.splitlines() if x.startswith(tag+' ')]
  if len(rows)!=1:raise ValueError(tag)
  return rows[0]
 h,regs=collect(s);root=ET.parse(s/'apollo-dfp-research-01/apollo510.svd').getroot();mspi=next(x for x in root.findall('./peripherals/peripheral') if x.findtext('name')=='MSPI0');iom=next(x for x in root.findall('./peripherals/peripheral') if x.findtext('name')=='IOM0');r=next(x for x in mspi.findall('./registers/register') if x.findtext('name')=='CQFLAGS');ir=next(x for x in iom.findall('./registers/register') if x.findtext('name')=='CQFLAGS');check('exact-peripheral-and-offset',int(r.findtext('addressOffset'),0)==0x2b0 and int(ir.findtext('addressOffset'),0)==0x234);check('MSPI-mask-and-upper16-reserved',int(r.findtext('resetMask'),0)==0xffff and int(ir.findtext('resetMask'),0)==0xffffffff);field=next(x for x in r.findall('./fields/field') if x.findtext('name')=='CQFLAGS');enum={x.findtext('name'):dict(value=int(x.findtext('value'),0),description=x.findtext('description')) for x in field.findall('./enumeratedValues/enumeratedValue')};expected={'STOP':0x8000,'CQIDX':0x4000,'BUF1XOREN':0x2000,'BUF0XOREN':0x1000,'DMACPL':0x800,'CMDCPL':0x400,'IOM1READY':0x200,'IOM0READY':0x100};check('hardware-bit-values',all(enum[k]['value']==v for k,v in expected.items()));check('software-bits',all(enum['SWFLAG'+str(n)]['value']==1<<n for n in range(8)));check('completion-index-source', 'STATUS bit in CTRL' in enum['CMDCPL']['description'] and 'DMASTAT' in enum['DMACPL']['description'] and 'match' in enum['CQIDX']['description']);(o/'MSPI-CQFLAGS.json').write_text(json.dumps(enum,indent=2)+'\n')
 cf=next(x for x in mspi.findall('./registers/register') if x.findtext('name')=='MSPICFG');sel=next(x for x in cf.findall('./fields/field') if x.findtext('name')=='IOMSEL');routes={x.findtext('name'):int(x.findtext('value'),0) for x in sel.findall('./enumeratedValues/enumeratedValue')};check('routing7-is-IOM7-not-disabled',routes['IOM7']==7 and routes['DISABLED']==15)
 src=s/'mspi1-source-research-01';hal=(src/'am_hal_mspi.c').read_bytes();pin=next(x for x in json.loads((src/'sources.json').read_text())['files'] if x['path'].endswith('/am_hal_mspi.c'));check('HAL-pin',hashlib.sha256(hal).hexdigest()==pin['sha256']);text=hal.decode();check('HAL-save-full-flags','pMSPIState->registerState.regCQFLAGS          = MSPIn(pMSPIState->ui32Module)->CQFLAGS;' in text);check('HAL-restore-only-low8','AM_HAL_MSPI_SC_SET(pMSPIState->registerState.regCQFLAGS & 0xFF)' in text)
 md=Cs(CS_ARCH_ARM,CS_MODE_THUMB|CS_MODE_MCLASS)
 for key,bundle,hal_delta,driver_delta in [('stock24','stock-2.4.0.24.bin',0,0),('stock23','stock-2.3.0.24.bin',0xd3d4,0x4d18),('cfw','faceclaw-38-research-only.bin',0xd3d4,0x4d18)]:
  d=s/'mspi1-write-disable-main-01'/key;_,raw=load_pinned_main((s/'inputs/verified-01'/bundle).read_bytes());check(key+'-original-main',raw==(d/'main.bin').read_bytes());log=(d/'renode.log').read_text();v=parse_log(log);check(key+'-saved-report',v==json.loads((d/'report.json').read_text())['observed']);entry=0x4e8f8c-hal_delta;target=0x4e92dc-hal_delta;end=0x4e94d0-hal_delta;code=list(md.disasm(raw[entry-0x438000:end-0x438000],entry));m={x.address:(x.mnemonic,x.op_str) for x in code};check(key+'-entry',m.get(entry)==('push','{r4, r5, r6, lr}'));expected_save={target:('ldr.w','r1, [r1, #0x2b0]'),target+4:('str.w','r1, [r5, #0x8b8]'),target+8:('ldr','r1, [r5, #4]')};check(key+'-actual-full-word-save',v['pc']==target and all(m.get(x)==p for x,p in expected_save.items()));rr=0x4e9128-hal_delta;check(key+'-restore-low-byte-only',m.get(rr)==('ldrb.w','r2, [r5, #0x8b8]') and m.get(rr+4)==('and','r2, r2, #0xff') and m.get(rr+8)==('str.w','r2, [r1, #0x2b4]'))
  caller=0x47a89a-driver_delta;cc={x.address:(x.mnemonic,x.op_str) for x in md.disasm(raw[caller-0x438000:caller+0x20-0x438000],caller)};check(key+'-retain-call-arguments',cc.get(caller)==('push','{r4, lr}') and cc.get(caller+0xc)==('movs','r2, #1') and cc.get(caller+0xe)==('movs','r1, #2') and cc.get(caller+0x16)==('bl','#'+hex(entry)) and v['register_context']['r14']==caller+0x1b);state=v['register_context']['r5'];check(key+'-snapshot-buffer-bounds',state%4==0 and 0x20000000<=state+0x8b8<=0x20380000-4)
  cfg=marker(log,'BLACKWALL_MSPI1_CONFIG')['registers'];cq=marker(log,'BLACKWALL_MSPI1_CQ_INIT')['registers'];pio=marker(log,'BLACKWALL_MSPI1_SAMPLING');check(key+'-disabled-queue-DMA-and-known-PIO-completion',cq['672']==2 and cfg['256']==0 and pio['control']&2==2 and not pio['busy']);check(key+'-software-and-indices',cq['688']==0x80 and cq['704']==cq['708']==0);check(key+'-selected-IOM7',((cfg['48']>>4)&15)==7);known=0x80|0x400|0x4000;check(key+'-nonzero-known-bits',known==0x4480);cases.append(dict(case=key,save_PC=hex(target),snapshot=hex(state+0x8b8),restore_PC=hex(rr),known_under_disabled_model=hex(known),known_mask=hex(0xccff),unknown_handshake_mask=hex(0x3300),mock_levels0_example=hex(known|0x300),mock_levels3_example=hex(known|0x3000),actual_handshake_levels_verified=False,CQ_execution_verified=False));(o/(key+'-retention.asm')).write_text('\n'.join(hex(x.address)+' '+x.mnemonic+' '+x.op_str for x in code)+'\n')
 (o/'report.json').write_text(json.dumps(dict(passed=True,count=len(checks),checks=checks,cases=cases,scope='MSPI metadata and saved original retention contract only; known bits derive from current disabled digital model, external handshake and full read still unimplemented'),indent=2)+'\n');print(json.dumps(dict(passed=True,count=len(checks))))
